"""Evidence data model.

The model enforces the distinction the whole project is built on:

* ``observed``      - a directly measured technical fact (bytes, sample values, a header field).
* ``statistical``   - a measurement that is unusual *relative to the file's own baseline*.
* ``explanation``   - a possible explanation generated by the correlation engine.
* ``undetermined``  - something the available data cannot establish.

A finding never carries a probability. Severity is an ordinal description of how
unusual the observation is for an unedited recording, not of how likely tampering is.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any


class Category(str, Enum):
    OBSERVED = "observed"
    STATISTICAL = "statistical"
    EXPLANATION = "explanation"
    UNDETERMINED = "undetermined"


class Severity(str, Enum):
    INFO = "info"
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"


SEVERITY_RANK = {Severity.INFO: 0, Severity.LOW: 1, Severity.MEDIUM: 2, Severity.HIGH: 3}


class Localization(str, Enum):
    POINT = "point"  # a single instant (edit point candidate)
    REGION = "region"  # a span with meaningful boundaries
    GLOBAL = "global"  # a property of the whole file


def _clean(v: Any) -> Any:
    """Convert numpy scalars/arrays to JSON-friendly Python values."""
    try:
        import numpy as np
    except ImportError:  # pragma: no cover
        np = None
    if np is not None:
        if isinstance(v, np.generic):
            v = v.item()
        elif isinstance(v, np.ndarray):
            v = v.tolist()
    if isinstance(v, float):
        if v != v or v in (float("inf"), float("-inf")):
            return None
        return round(v, 6)
    if isinstance(v, dict):
        return {str(k): _clean(x) for k, x in v.items()}
    if isinstance(v, (list, tuple)):
        return [_clean(x) for x in v]
    if isinstance(v, Enum):
        return v.value
    return v


@dataclass
class Finding:
    finding_id: str
    test_id: str
    module: str
    method: str
    family: str
    category: Category
    severity: Severity
    title: str
    description: str
    localization: Localization = Localization.GLOBAL
    time_start: float | None = None
    time_end: float | None = None
    sample_start: int | None = None
    sample_end: int | None = None
    measurements: dict = field(default_factory=dict)
    baseline: dict = field(default_factory=dict)
    alternative_explanations: list[str] = field(default_factory=list)
    limitations: list[str] = field(default_factory=list)
    supporting_evidence: list[str] = field(default_factory=list)

    def to_dict(self) -> dict:
        return _clean({
            "finding_id": self.finding_id,
            "test_id": self.test_id,
            "module": self.module,
            "method": self.method,
            "family": self.family,
            "category": self.category,
            "severity": self.severity,
            "title": self.title,
            "description": self.description,
            "localization": self.localization,
            "time_start": self.time_start,
            "time_end": self.time_end,
            "sample_start": self.sample_start,
            "sample_end": self.sample_end,
            "measurements": self.measurements,
            "baseline": self.baseline,
            "alternative_explanations": self.alternative_explanations,
            "limitations": self.limitations,
            "supporting_evidence": self.supporting_evidence,
        })


@dataclass
class TestResult:
    """Outcome of one forensic test, including tests that found nothing."""

    test_id: str
    name: str
    module: str
    family: str
    status: str = "completed"  # completed | not_applicable | error
    summary: str = ""
    score: float | None = None
    threshold: float | None = None
    score_name: str = ""
    detected: bool = False
    experimental: bool = False
    measurements: dict = field(default_factory=dict)
    finding_ids: list[str] = field(default_factory=list)
    limitations: list[str] = field(default_factory=list)

    def to_dict(self) -> dict:
        return _clean(dict(self.__dict__))


class EvidenceRegistry:
    """Collects findings and test results and assigns stable, readable identifiers."""

    def __init__(self) -> None:
        self.findings: list[Finding] = []
        self.tests: list[TestResult] = []
        self._counters: dict[str, int] = {}

    def add_finding(self, prefix: str, **kwargs: Any) -> Finding:
        n = self._counters.get(prefix, 0) + 1
        self._counters[prefix] = n
        finding = Finding(finding_id=f"{prefix}-{n:03d}", **kwargs)
        self.findings.append(finding)
        return finding

    def add_test(self, test: TestResult) -> TestResult:
        self.tests.append(test)
        return test

    def by_test(self, test_id: str) -> list[Finding]:
        return [f for f in self.findings if f.test_id == test_id]

    def get(self, finding_id: str) -> Finding | None:
        return next((f for f in self.findings if f.finding_id == finding_id), None)
